"""Shared terminal metadata vectors generated by actual Processing validators."""
import json
from pathlib import Path
import unittest

from processing import reference_protocol as protocol
from processing.reference_failure import FAILURE_FIELDS, validate_failure
from processing.reference_terminal import FIELDS, validate_terminal_acceptance
from processing.maintenance import Conflict


class TerminalContractTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.contract = json.loads((Path(__file__).parents[1] /
            'contracts/reference-terminal-v1.contract.json').read_text())
        cls.valid = {row['name']: row for row in cls.contract['valid']}

    def failure(self, value, expected):
        return validate_failure(value, job_id=expected['jobId'],
            generation=expected['generation'], environment=expected['environment'],
            input_manifest_sha256=expected['inputManifestSha256'],
            pipeline_digest=expected['pipelineDigest'])

    def test_generated_positive_bytes_hashes_and_closed_fields(self):
        self.assertEqual(len(self.valid), 3)
        for row in self.valid.values():
            with self.subTest(name=row['name']):
                failure, acceptance = row['outcome'], row['acceptance']
                self.assertEqual(set(failure), set(FAILURE_FIELDS))
                self.assertEqual(set(acceptance), set(FIELDS))
                self.assertEqual(self.failure(failure, failure), failure)
                self.assertEqual(validate_terminal_acceptance(acceptance,
                    failure=failure), acceptance)
                self.assertEqual(protocol.canonical_json(failure).decode(),
                    row['outcomeCanonicalUtf8'])
                self.assertEqual(protocol.canonical_json(acceptance).decode(),
                    row['acceptanceCanonicalUtf8'])
                self.assertEqual(protocol.digest(acceptance), row['acceptanceSha256'])
                self.assertEqual(protocol.digest({k: v for k, v in failure.items()
                    if k != 'failureSha256'}), failure['failureSha256'])

    def test_generated_negative_vectors_reject(self):
        self.assertEqual(len(self.contract['invalid']), 12)
        for row in self.contract['invalid']:
            error = {'Conflict': Conflict, 'ProtocolError': protocol.ProtocolError}[
                row['expectedValidationError']]
            with self.subTest(name=row['name']), self.assertRaises(error):
                expected = self.valid[row['base']]['outcome']
                if row['kind'] == 'outcome':
                    self.failure(row['value'], expected)
                else:
                    validate_terminal_acceptance(row['value'], failure=expected)

    def test_negative_vectors_have_exactly_one_typed_field_delta(self):
        for row in self.contract['invalid']:
            with self.subTest(name=row['name']):
                base = self.valid[row['base']][row['kind']]
                value = row['value']
                changed = {key for key in set(base) | set(value)
                    if key not in base or key not in value
                    or type(base[key]) is not type(value[key]) or base[key] != value[key]}
                self.assertEqual(changed, {row['mutatedField']})
                if row['kind'] == 'acceptance' and row['mutatedField'] != 'acceptedAt':
                    self.assertEqual(value['acceptedAt'], base['acceptedAt'])

    def test_confirmed_failure_and_cancellation_do_not_claim_files(self):
        self.assertEqual({r['outcome']['terminalState'] for r in self.valid.values()},
            {'failed', 'cancelled'})
        for row in self.valid.values():
            self.assertFalse(set(row['outcome']) & {'paths', 'objects', 'resultManifest'})
            self.assertFalse(set(row['acceptance']) & {'filesAccepted', 'sourceReleased'})


if __name__ == '__main__':
    unittest.main()
